        responseBody = "{\"status\":\"approved\",\"id\":\"auth_1\",\"risk\":{\"score\":3}}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unrecognised_or_missing_status_is_never_treated_as_approved() {
        responseBody = "{\"status\":\"pending\"}";
        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);

        responseBody = "{}";
        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);

        responseBody = "{\"status\":\"APPROVED\"}";
        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_is_read_as_declined_even_if_the_body_claims_approval() {
        status = 402;
        responseBody = "{\"status\":\"approved\"}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_with_an_empty_body_is_declined() {
        status = 402;
        responseBody = "";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void other_error_statuses_are_failures_not_declines() {
        for (int error : new int[] {400, 401, 500, 503}) {
            status = error;
            responseBody = "{\"status\":\"declined\"}";

            assertThatThrownBy(this::authorize)
                    .as("status %d", error)
                    .isInstanceOf(IllegalStateException.class)
                    .hasMessageContaining(String.valueOf(error));
        }
    }

    @Test
    void a_malformed_answer_is_a_failure_and_not_an_approval() {
        responseBody = "not json";

        assertThatThrownBy(this::authorize).isNotInstanceOf(AssertionError.class);
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));
    }
